    [StructLayout(LayoutKind.Sequential)]
    public unsafe struct SturdyAccelerationStructureBuildRangeInfo
    {
        public uint primitive_count;
        public uint primitive_offset;
        public uint first_vertex;
        public uint transform_offset;
    }

